package firstjava;
import java.math.BigDecimal;
import java.math.BigInteger;

public class Datatypes {

	public static void main(String[] args) {
		BigInteger b1=new BigInteger("9876543212345678909876543234567898765409876543234567890");
		BigInteger b2=new BigInteger("");
		System.out.println(b1.add(b2));
		System.out.println(b1.multiply(b2));
		System.out.println(b1.subtract(b2));
		System.out.println(b1.pow(8));



		BigDecimal d1=new BigDecimal("9888888913469133333331975308680246800864197756890987654456789");
		BigDecimal d2=new BigDecimal("987654323456789876544.0987654345678909876543456890987654456789");
	
		
		System.out.println(d1.add(d2));
		System.out.println(d2.pow(8));
		System.out.println(d1);


		

		

	}

}
